package pl.polsl.model;

import pl.polsl.enums.Action;
import java.time.LocalDateTime;
import lombok.AllArgsConstructor;
import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;



/**
 * Activity log model. Describes a single action performed by a user on stored passwords.
 * Getters, setters and constructors (no-arguments and all-arguments) are generated by Lombok
 *
 * @author Rafał Malinowski
 * @version 1
 */
@Getter @Setter
@NoArgsConstructor
@AllArgsConstructor
public class ActivityLog {
    /**
     * Date and time of the action
     */
    private LocalDateTime data;
    /**
     * Type of the performed action
     */
    private Action action;
    /**
     * Origin of the password the action was performed on
     */
    private String origin;
    /**
     * Additional details about the action
     */
    private String details;
    /**
     * Id of the user who performed the action
     */
    private int userId;
}
